package com.coworkhub.config;
import io.swagger.v3.oas.models.OpenAPI;import io.swagger.v3.oas.models.info.Info;import io.swagger.v3.oas.models.Components;import io.swagger.v3.oas.models.security.SecurityScheme;import io.swagger.v3.oas.models.security.SecurityRequirement;import org.springframework.context.annotation.Bean;import org.springframework.context.annotation.Configuration;import org.springdoc.core.models.GroupedOpenApi;
@Configuration public class OpenApiConfig {@Bean public OpenAPI coworkHubOpenApi(){return new OpenAPI().info(new Info().title("CoWorkHub API").version("1.0.0").description("API REST para gestión de sedes, salas, miembros, membresías y reservas de coworking. Autenticación JWT mediante /auth/login.")).components(new Components().addSecuritySchemes("bearerAuth",new SecurityScheme().type(SecurityScheme.Type.HTTP).scheme("bearer").bearerFormat("JWT"))).addSecurityItem(new SecurityRequirement().addList("bearerAuth"));}@Bean public GroupedOpenApi coworkHubGroup(){return GroupedOpenApi.builder().group("CoWorkHub API").pathsToMatch("/api/**","/auth/**").build();}}
